import {militiaAt,militiaCount,militiaMinutes,sectorLeadership} from './overmap-militia.js';
import {ensureLogistics,advanceLogistics,startMilitiaTraining,cancelMilitiaTraining,resolveLogisticsEncounter} from './overmap-logistics.js';
import {formatClock} from './game-clock.js';
export function logisticsPanel({session,map,selected,action,destination}){
 const host=document.createElement('section');host.className='generation-panel';host.id='logistics-panel';host.innerHTML='<h2>Fortresses and weapons</h2><p class="note">Strategic tester: shipments carry one recruitment batch. Each squad contains four troops. Militia batches recruit or upgrade four people. Test treasury starts at $5,000. Tactical battle maps are not assigned; contacts pause at an encounter handoff. Required victories must come from combat; the test control below simulates that result.</p><p id="logistics-money"></p><div class="generation-controls"><button id="logistics-day">Advance 1 day</button><button id="logistics-week">Advance 7 days</button><button id="militia-train">Train / upgrade 4 militia · $500</button><button id="militia-cancel">Cancel training (no refund)</button></div><p id="militia-status"></p><div id="logistics-encounter"></div><div id="logistics-forts"></div><div id="logistics-convoys"></div><div id="logistics-raiders"></div><details><summary>Logistics log</summary><ol id="logistics-log"></ol></details>';
 document.getElementById('travel-note').parentElement.after(host);const $=id=>document.getElementById(id);
 $('logistics-day').onclick=()=>action(()=>advanceLogistics(session(),map(),1440));$('logistics-week').onclick=()=>action(()=>advanceLogistics(session(),map(),7*1440));
 $('militia-train').onclick=()=>action(()=>startMilitiaTraining(session(),map(),selected()?.id));$('militia-cancel').onclick=()=>action(()=>cancelMilitiaTraining(session(),selected()?.id));
 const coord=i=>`${i%30+1},${Math.floor(i/30)+1}`;
 function list(id,entries,describe,target){const el=$(id);el.replaceChildren();for(const item of entries){const p=document.createElement('p');p.textContent=describe(item)+' ';if(target){const button=document.createElement('button');button.textContent='Send selected group';button.disabled=!selected()||!!session().logistics.pending;button.onclick=()=>destination(target(item));p.append(button);}el.append(p);}}
 return {render(){const s=session(),l=ensureLogistics(s,map()),g=selected();$('logistics-money').textContent=`Treasury $${l.money} · Captured weapons batches ${l.weapons} · Militia ${Object.values(l.militia).reduce((a,b)=>a+militiaCount(b),0)}`;
  const roster=g?militiaAt(s,map(),g.state.position):null;
  $('militia-status').textContent=g?.training?`${g.name} training at ${coord(g.training.sector)} until ${formatClock({minutes:g.training.endsAt})}.`: 'Training occupies the selected group. Best leadership in the sector sets duration: 4 days at 1, 3 at 50, 2 at 100. Basic: pistols/rifles; medium: SMGs/assault rifles; high: sniper rifles/machine guns.';
  if(roster)$('militia-status').textContent+=` Town militia: ${roster.basic} basic, ${roster.medium} medium, ${roster.high} high · ${roster.rounds}/6 batches completed.${g.training?'':` Next batch: ${(militiaMinutes(sectorLeadership(s,g.state.position))/1440).toFixed(2)} days · ${l.militiaCost}.`}`;
  $('militia-train').disabled=!g||!!g.firstAid||!!g.rest||!!g.training||!!g.state.route.length||!!l.pending||roster?.rounds>=6||roster?.high===8;$('militia-cancel').disabled=!g?.training||!!l.pending;for(const id of ['logistics-day','logistics-week'])$(id).disabled=!!l.pending;
  const encounter=$('logistics-encounter');encounter.replaceChildren();if(l.pending){const p=document.createElement('p');p.textContent=`Encounter required: ${l.pending.kind} at ${coord(l.pending.sector)}. Strategic time is paused.`;const b=document.createElement('button');b.textContent='TEST ONLY: record player victory';b.onclick=()=>action(()=>resolveLogisticsEncounter(s,'player-victory'));encounter.append(p,b);}
  list('logistics-forts',l.forts,f=>`Fort ${coord(f.index)} · ${f.owner} · Weapons ${f.stock} · ${f.readyAt===null?'Awaiting weapons': 'Recruitment ready '+formatClock({minutes:f.readyAt})}`,f=>f.index);
  list('logistics-convoys',l.convoys,c=>`Weapons convoy at ${coord(c.state.position)} → fort ${coord(c.fort)}`,c=>c.state.route[0]?.to??c.state.position);
  list('logistics-raiders',l.raiders,r=>`Red Hat squad at ${coord(r.state.position)} → ${r.target===null?'waiting for reachable mercenaries':coord(r.target)}`,r=>r.state.route[0]?.to??r.state.position);
  $('logistics-log').replaceChildren(...l.log.slice(-12).reverse().map(row=>{const li=document.createElement('li');li.textContent=formatClock({minutes:row.time})+' · '+row.text;return li;}));
 }};
}
